UPDATE bot_definitions SET config_schema = '[{"default": "true", "key": "enabled", "label": "Bot actif", "required": false, "type": "boolean"}, {"key": "alert_channel_id", "label": "Salon d alertes", "required": false, "type": "channel"}, {"key": "log_channel_id", "label": "Salon de logs", "required": false, "type": "channel"}, {"default": "10", "key": "raid_join_threshold", "label": "Seuil raid (nombre de joins)", "required": false, "type": "number"}, {"default": "10", "key": "raid_join_window_secs", "label": "Fenetre raid (secondes)", "required": false, "type": "number"}, {"default": "86400", "key": "min_account_age_secs", "label": "Age minimum du compte (secondes)", "required": false, "type": "number"}, {"default": "false", "key": "quarantine_enabled", "label": "Quarantaine activee", "required": false, "type": "boolean"}, {"key": "quarantine_role_id", "label": "Role de quarantaine", "required": false, "type": "role"}, {"default": "false", "key": "captcha_enabled", "label": "Captcha active", "required": false, "type": "boolean"}, {"default": "0", "key": "slowmode_seconds", "label": "Slowmode anti-raid (secondes, 0 = desactive)", "required": false, "type": "number"}, {"default": "false", "key": "lockdown_enabled", "label": "Lockdown auto (desactive envoi messages)", "required": false, "type": "boolean"}, {"default": "300", "key": "lockdown_duration_secs", "label": "Duree max du lockdown (secondes)", "required": false, "type": "number"}, {"default": "button", "key": "captcha_type", "label": "Type de captcha (button, math)", "required": false, "type": "text"}, {"default": "false", "key": "alt_detection_enabled", "label": "Detection de comptes alt", "required": false, "type": "boolean"}, {"default": "604800", "key": "alt_retention_secs", "label": "Retention bans pour detection alt (secondes)", "required": false, "type": "number"}, {"default": "2", "key": "alt_name_distance", "label": "Seuil distance Levenshtein (noms alt)", "required": false, "type": "number"}, {"defa