t_response_minutes", "label": "SLA premiere reponse (minutes, 0=desactive)", "required": false, "type": "number"}, {"default": "60", "key": "sla_escalation_minutes", "label": "Delai escalade auto (minutes, 0=desactive)", "required": false, "type": "number"}, {"default": "true", "key": "satisfaction_enabled", "label": "Sondage satisfaction apres fermeture", "required": false, "type": "boolean"}, {"default": "", "key": "response_templates", "label": "Templates de reponses (format: label|contenu, un par ligne)", "required": false, "type": "text"}, {"default": "", "key": "faq_entries", "label": "FAQ (format: question|reponse, une par ligne)", "required": false, "type": "text"}, {"default": "text", "key": "transcript_format", "label": "Format transcript (text, markdown, html)", "required": false, "type": "text"}]'::jsonb WHERE bot_name = 'ticket-bot';

